"""Run once from the src folder:  python install_ui.py
Creates app.py, templates/ and static/ for the Intze Tank web app."""
import base64, os
FILES = {
    'app.py': '',
    'static/style.css': '',
    'templates/advice.html': '',
    'templates/base.html': '',
    'templates/denied.html': '',
    'templates/empty.html': '',
    'templates/login.html': '',
    'templates/overview.html': '',
    'templates/site_desk.html': '',
}
for path, data in FILES.items():
    folder = os.path.dirname(path)
    if folder:
        os.makedirs(folder, exist_ok=True)
    with open(path, "wb") as fh:
        fh.write(base64.b64decode(data))
    print("written", path)
print("Done. Next: python app.py")
